package computeenvs

import (
	"encoding/json"
	"fmt"
	"strconv"
	"strings"
)

// The Terraform resources keep their v1-shaped models, generated by Speakeasy from the v1 OpenAPI description. This
// file translates those models to the API v2 wire format and back. It changes the shape of the payloads only: it adds
// no rule of its own, and the v2 server validates what it receives.

// v1 config discriminator -> v2 config platform.
var v2PlatformOf = map[string]string{
	"aws-batch":              "AWS_BATCH",
	"aws-cloud":              "AWS_CLOUD",
	"seqeracompute-platform": "SEQERA_COMPUTE",
	"google-batch":           "GOOGLE_BATCH",
	"google-cloud":           "GOOGLE_CLOUD",
	"google-lifesciences":    "GOOGLE_LIFE_SCIENCES",
	"azure-batch":            "AZURE_BATCH",
	"azure-cloud":            "AZURE_CLOUD",
	"k8s-platform":           "K8S",
	"eks-platform":           "EKS",
	"gke-platform":           "GKE",
	"uge-platform":           "UGE",
	"slurm-platform":         "SLURM",
	"lsf-platform":           "LSF",
	"altair-platform":        "ALTAIR_PBS",
	"moab-platform":          "MOAB",
	"local-platform":         "LOCAL",
}

var v1PlatformOf = invert(v2PlatformOf)

// Fields renamed between the v1 and v2 configuration models, by v1 discriminator, as v1 path -> v2 path.
var renamedFields = map[string]map[string]string{
	"aws-batch": {
		"nvnmeStorageEnabled": "nvmeStorageEnabled",
	},
	"azure-batch": {
		"forge.bootDiskSizeGB":            "forge.bootDiskSizeGb",
		"forge.headPool.bootDiskSizeGB":   "forge.headPool.bootDiskSizeGb",
		"forge.workerPool.bootDiskSizeGB": "forge.workerPool.bootDiskSizeGb",
	},
	"azure-cloud": {
		"bootDiskSizeGB": "bootDiskSizeGb",
	},
}

// Enum values spelled differently in v1 and v2, by field name, as v1 value -> v2 value.
var renamedValues = map[string]map[string]string{
	"schedConfig.provisioningModel": {"spot": "SPOT", "spotFirst": "SPOT_FIRST", "ondemand": "ON_DEMAND"},
	"podCleanup":                    {"on_success": "ON_SUCCESS", "always": "ALWAYS", "never": "NEVER"},
}

// Configuration fields the v2 write model does not carry, by v1 discriminator: either v1-only fields with no v2
// counterpart, or fields v2 documents as set by the server from the resources it provisions. They are not sent.
var unwritableFields = map[string][]string{
	"aws-batch":    {"lustreId", "storageType"},
	"aws-cloud":    {"subnetId", "schedConfig.diskAllocation"},
	"google-cloud": {"zone", "serviceAccountEmail", "schedConfig.diskAllocation"},
	"azure-batch":  {"autoPoolMode", "deleteJobsOnCompletion", "forge.dualPoolConfig"},
	"azure-cloud": {
		"dataCollectionEndpoint", "dataCollectionRuleId", "logTableName", "logWorkspaceId",
		"managedIdentityClientId", "managedIdentityId", "resourceGroup", "schedConfig.diskAllocation",
	},
	"eks-platform":   {"server", "sslCert"},
	"gke-platform":   {"server", "sslCert"},
	"local-platform": {"schedConfig.diskAllocation"},
}

// toV2WriteModel turns a v1 create request body (`{"computeEnv": {...}, "labelIds": [...]}`) into a v2
// ComputeEnvWriteModel document.
func toV2WriteModel(v1Body []byte) ([]byte, error) {
	var req struct {
		ComputeEnv map[string]any `json:"computeEnv"`
		LabelIds   []int64        `json:"labelIds"`
	}
	if err := json.Unmarshal(v1Body, &req); err != nil {
		return nil, fmt.Errorf("reading the compute environment to create: %w", err)
	}
	ce := req.ComputeEnv
	if ce == nil {
		return nil, fmt.Errorf("the request carries no compute environment")
	}

	out := map[string]any{}
	for _, field := range []string{"name", "description", "credentialsId", "managedIdentityId", "fusionMetricsCollectionEnabled"} {
		if v, ok := ce[field]; ok && v != nil {
			out[field] = v
		}
	}
	if len(req.LabelIds) > 0 {
		ids := make([]string, 0, len(req.LabelIds))
		for _, id := range req.LabelIds {
			ids = append(ids, strconv.FormatInt(id, 10))
		}
		out["resourceLabelIds"] = ids
	}

	config, _ := ce["config"].(map[string]any)
	if config == nil {
		config = map[string]any{}
	}
	discriminator, _ := config["discriminator"].(string)
	if discriminator == "" {
		// The platform-specific resources carry the platform at the top level only.
		discriminator, _ = ce["platform"].(string)
	}
	platform, ok := v2PlatformOf[discriminator]
	if !ok {
		return nil, fmt.Errorf("unknown compute environment platform %q", discriminator)
	}
	delete(config, "discriminator")
	for _, path := range unwritableFields[discriminator] {
		deletePath(config, path)
	}
	for from, to := range renamedFields[discriminator] {
		movePath(config, from, to)
	}
	for path, values := range renamedValues {
		mapValue(config, path, values)
	}
	config["platform"] = platform
	out["config"] = config

	return json.Marshal(out)
}

// toV1Describe turns a v2 ComputeEnvReadModel document into a v1 describe response body
// (`{"computeEnv": {...}}`), the shape the Terraform resources read their state from.
func toV1Describe(v2Body []byte, workspaceID int64) ([]byte, error) {
	var ce map[string]any
	if err := json.Unmarshal(v2Body, &ce); err != nil {
		return nil, fmt.Errorf("reading the compute environment: %w", err)
	}

	out := map[string]any{"workspaceId": workspaceID}
	for _, field := range []string{"id", "name", "description", "status", "message", "primary", "credentialsId", "managedIdentityId", "fusionMetricsCollectionEnabled", "resources"} {
		if v, ok := ce[field]; ok && v != nil {
			out[field] = v
		}
	}
	for v2Field, v1Field := range map[string]string{"createdAt": "dateCreated", "updatedAt": "lastUpdated", "lastUsedAt": "lastUsed"} {
		if v, ok := ce[v2Field]; ok && v != nil {
			out[v1Field] = v
		}
	}
	if labels, ok := ce["resourceLabels"].([]any); ok {
		v1Labels := make([]any, 0, len(labels))
		for _, l := range labels {
			label, _ := l.(map[string]any)
			if label == nil {
				continue
			}
			v1Label := map[string]any{"name": label["name"], "value": label["value"], "resource": true}
			if id, err := strconv.ParseInt(fmt.Sprint(label["id"]), 10, 64); err == nil {
				v1Label["id"] = id
			}
			v1Labels = append(v1Labels, v1Label)
		}
		out["labels"] = v1Labels
	}

	config, _ := ce["config"].(map[string]any)
	if config != nil {
		platform, _ := config["platform"].(string)
		discriminator, ok := v1PlatformOf[platform]
		if !ok {
			return nil, fmt.Errorf("unknown compute environment platform %q", platform)
		}
		delete(config, "platform")
		for path, values := range renamedValues {
			mapValue(config, path, invert(values))
		}
		for from, to := range renamedFields[discriminator] {
			movePath(config, to, from)
		}
		// v1 reports the AWS account of Seqera Compute at the top level.
		if account, ok := config["awsAccountId"]; ok {
			delete(config, "awsAccountId")
			if account != nil {
				out["awsAccountId"] = account
			}
		}
		config["discriminator"] = discriminator
		out["platform"] = discriminator
		out["config"] = config
	}

	return json.Marshal(map[string]any{"computeEnv": out})
}

// toV2Patch turns a v1 update request body into a v2 ComputeEnvPatchModel document. Both carry the same four fields,
// and both servers write the fields given a value and leave the ones given as null alone, so no update mask is sent.
func toV2Patch(v1Body []byte) ([]byte, error) {
	var req map[string]any
	if err := json.Unmarshal(v1Body, &req); err != nil {
		return nil, fmt.Errorf("reading the compute environment update: %w", err)
	}
	out := map[string]any{}
	for _, field := range []string{"name", "description", "credentialsId", "fusionMetricsCollectionEnabled"} {
		if v, ok := req[field]; ok && v != nil {
			out[field] = v
		}
	}
	return json.Marshal(out)
}

func split(path string) []string { return strings.Split(path, ".") }

func parentOf(m map[string]any, keys []string) map[string]any {
	for _, k := range keys[:len(keys)-1] {
		next, _ := m[k].(map[string]any)
		if next == nil {
			return nil
		}
		m = next
	}
	return m
}

func deletePath(m map[string]any, path string) {
	keys := split(path)
	if p := parentOf(m, keys); p != nil {
		delete(p, keys[len(keys)-1])
	}
}

func movePath(m map[string]any, from, to string) {
	fk, tk := split(from), split(to)
	src := parentOf(m, fk)
	if src == nil {
		return
	}
	v, ok := src[fk[len(fk)-1]]
	if !ok {
		return
	}
	delete(src, fk[len(fk)-1])
	if dst := parentOf(m, tk); dst != nil {
		dst[tk[len(tk)-1]] = v
	}
}

func mapValue(m map[string]any, path string, values map[string]string) {
	keys := split(path)
	p := parentOf(m, keys)
	if p == nil {
		return
	}
	if s, ok := p[keys[len(keys)-1]].(string); ok {
		if mapped, ok := values[s]; ok {
			p[keys[len(keys)-1]] = mapped
		}
	}
}

func invert(m map[string]string) map[string]string {
	out := make(map[string]string, len(m))
	for k, v := range m {
		out[v] = k
	}
	return out
}
